'use strict';

// MODULES //

var resolve = require( '@stdlib/blas/base/layout-resolve-enum' );
var addon = require( './../src/addon.node' );


// MAIN //

/**
* Generates a single-precision floating-point Vandermonde matrix.
*
* @param {string} order - storage layout
* @param {integer} mode - specifies whether columns should contain powers that are increasing or decreasing
* @param {NonNegativeInteger} M - number of rows in the matrix `Out`
* @param {NonNegativeInteger} N - number of columns in the matrix `Out`
* @param {Float32Array} x - input array
* @param {integer} strideX - stride length for `x`
* @param {Float32Array} out - output array
* @param {PositiveInteger} LDO - stride length for the leading dimension of `Out`
* @returns {Float32Array} output array
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
*
* var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );
* var out = new Float32Array( 9 );
*
* svander( 'row-major', -1, 3, 3, x, 1, out, 3 );
* // out => <Float32Array>[ 1.0, 1.0, 1.0, 4.0, 2.0, 1.0, 9.0, 3.0, 1.0 ]
*/
function svander( order, mode, M, N, x, strideX, out, LDO ) {
	addon( resolve( order ), mode, M, N, x, strideX, out, LDO );
	return out;
}


// EXPORTS //

module.exports = svander;
